// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightLinksValidator from 'starlight-links-validator';
import { sidebar } from './sidebar.mjs';

// https://astro.build/config
export default defineConfig({
  // Set `site` to the published URL when there is one: Starlight then writes the sitemap.
  integrations: [
    starlight({
      title: 'Frame Job',
      description:
        'The user documentation for Frame Job, a native macOS video editor that you, the built-in Assistant or any MCP agent can drive.',
      logo: { src: './src/assets/logo.svg', alt: 'Frame Job' },
      favicon: '/favicon.svg',
      social: [
        { icon: 'github', label: 'GitHub', href: 'https://github.com/kpgalligan/framejob' },
      ],
      editLink: { baseUrl: 'https://github.com/kpgalligan/framejob/edit/main/docs/site/' },
      customCss: [
        '@fontsource-variable/source-sans-3/index.css',
        '@fontsource/ibm-plex-mono/400.css',
        '@fontsource/ibm-plex-mono/500.css',
        '@fontsource/darker-grotesque/800.css',
        '@fontsource/darker-grotesque/900.css',
        './src/styles/frame-job.css',
      ],
      expressiveCode: { styleOverrides: { borderRadius: '0' } },
      plugins: [starlightLinksValidator()],
      sidebar,
    }),
  ],
});

/* Frame Job's look on Starlight: the mark's three inks, the app's three faces and its square
   chrome (designs/design_handoff_sharp/README.md). A video editor's chrome stays neutral, so the
   greys are neutral too and colour is kept for accents. */

:root {
  --fj-forest: #1f8564;
  --fj-butter: #f2c14e;
  --fj-coral: #f4653f;
  --fj-cream: #fbf8f1;

  --sl-font: 'Source Sans 3 Variable', ui-sans-serif, system-ui, sans-serif;
  --sl-font-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  --fj-font-display: 'Darker Grotesque', var(--sl-font);

  --sl-text-base: 1.0625rem;
  --sl-line-height: 1.6;
}

/* Dark is the app's authoritative look. */
:root,
::backdrop {
  --sl-color-accent-low: #12382c;
  --sl-color-accent: #2fa880;
  --sl-color-accent-high: #a6e6cf;

  --sl-color-white: #ffffff;
  --sl-color-gray-1: #ececec;
  --sl-color-gray-2: #c8c8c8;
  --sl-color-gray-3: #9c9c9c;
  --sl-color-gray-4: #6a6a6a;
  --sl-color-gray-5: #3b3b3b;
  --sl-color-gray-6: #262626;
  --sl-color-black: #181818;
}

:root[data-theme='light'],
[data-theme='light'] ::backdrop {
  --sl-color-accent-low: #cfeee2;
  --sl-color-accent: var(--fj-forest);
  --sl-color-accent-high: #124e3b;

  --sl-color-white: #1a1a1a;
  --sl-color-gray-1: #2b2b2b;
  --sl-color-gray-2: #474747;
  --sl-color-gray-3: #6b6b6b;
  --sl-color-gray-4: #989898;
  --sl-color-gray-5: #d3d0c8;
  --sl-color-gray-6: #eeeae1;
  --sl-color-gray-7: #f6f3ec;
  --sl-color-black: var(--fj-cream);
}

/* ---- Type ---- */

.site-title {
  font-family: var(--fj-font-display);
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}

.sl-markdown-content h1,
h1#_top,
.hero h1 {
  font-family: var(--fj-font-display);
  font-weight: 900;
  letter-spacing: -0.015em;
  line-height: 1.05;
}

h1#_top {
  font-size: clamp(2.4rem, 4vw, 3.1rem);
}

.sl-markdown-content h2 {
  font-family: var(--fj-font-display);
  font-weight: 800;
  font-size: 1.95rem;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.sl-markdown-content h3 {
  font-weight: 650;
  font-size: 1.2rem;
}

/* ---- Square chrome ---- */

.sl-link-button,
.card,
.sl-link-card,
starlight-tabs,
.sl-badge,
.starlight-aside,
site-search button,
.pagination-links a,
.sl-markdown-content code:not(pre code),
.sl-markdown-content img,
.sl-markdown-content figure,
starlight-theme-select select,
select {
  border-radius: 0 !important;
}

.sl-markdown-content code:not(pre code) {
  font-size: 0.86em;
}

/* Keys, as the app prints them: ⌘T. */
kbd,
.fj-keys {
  font-family: var(--sl-font-mono);
  font-size: 0.86em;
  padding: 0.08em 0.38em;
  background: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-gray-5);
  border-bottom-width: 2px;
  white-space: nowrap;
}

/* ---- Tables ---- */

.sl-markdown-content table {
  display: table;
  width: 100%;
  font-size: 0.96em;
}

.sl-markdown-content table th {
  text-align: start;
}

/* ---- The hero ---- */

.hero {
  padding-block: clamp(2rem, 5vw, 4rem);
}

.hero h1 {
  font-size: clamp(3.2rem, 7vw, 5rem);
}

.hero .tagline {
  color: var(--sl-color-gray-2);
  max-width: 34rem;
}

/* The playhead: coral on the primary action, as in the app. */
.sl-link-button.primary {
  background: var(--fj-coral);
  border-color: var(--fj-coral);
  color: #1a1a1a;
  font-weight: 600;
}

/* ---- Screens: both looks are in the page, the theme shows one. ---- */

.fj-shot {
  margin-block: 1.5rem;
}

.fj-shot img {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--sl-color-gray-5);
}

.fj-shot figcaption {
  margin-top: 0.4rem;
  color: var(--sl-color-gray-3);
  font-size: 0.9em;
}

:root[data-theme='light'] .fj-shot .fj-dark,
:root:not([data-theme='light']) .fj-shot .fj-light {
  display: none;
}

/* A narrow capture, such as the inspector alone, should not fill the column. */
.fj-shot.fj-narrow {
  max-width: 22rem;
}

/* ---- At a glance ---- */

.fj-glance {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 0.25rem 1.25rem;
  margin-block: 1.25rem;
  padding: 0.75rem 1rem;
  background: var(--sl-color-gray-6);
  border-inline-start: 3px solid var(--sl-color-accent);
  font-size: 0.95em;
}

.fj-glance dt {
  color: var(--sl-color-gray-3);
  margin: 0;
  font-weight: 400;
}

.fj-glance dd {
  margin: 0;
}

.fj-glance dd > * + * {
  margin-inline-start: 0.35em;
}

/* ---- The feature index ---- */

.fj-filter {
  position: sticky;
  top: calc(var(--sl-nav-height) + 0.5rem);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-block: 1rem 2rem;
  padding: 0.6rem 0.75rem;
  background: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-gray-5);
}

.fj-filter input {
  flex: 1;
  min-width: 0;
  padding: 0.35rem 0.5rem;
  font: inherit;
  color: var(--sl-color-white);
  background: var(--sl-color-black);
  border: 1px solid var(--sl-color-gray-5);
  border-radius: 0;
}

.fj-filter output {
  color: var(--sl-color-gray-3);
  font-size: 0.9em;
  white-space: nowrap;
}

.fj-features td:first-child {
  min-width: 11rem;
}

.fj-features td.fj-where {
  color: var(--sl-color-gray-2);
  font-size: 0.92em;
}

.fj-section[hidden],
.fj-features tr[hidden] {
  display: none;
}

---
// One screen of the app, captured in both looks; the page's theme shows the matching one.
// `name` is a capture's file name without its look: `05-clip-picture.inspector` reads
// src/assets/screens/05-clip-picture.inspector.{light,dark}.webp. An unknown name fails the build.
import { Image } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  name: string;
  alt: string;
  caption?: string;
  narrow?: boolean;
}

const { name, alt, caption, narrow = false } = Astro.props;

const screens = import.meta.glob<{ default: ImageMetadata }>('../assets/screens/*.webp', {
  eager: true,
});

function shot(look: 'light' | 'dark') {
  const found = screens[`../assets/screens/${name}.${look}.webp`];
  if (!found) throw new Error(`Shot: no ${look} capture named "${name}" in src/assets/screens/`);
  return found.default;
}

const light = shot('light');
const dark = shot('dark');
---

<figure class:list={['fj-shot', { 'fj-narrow': narrow }]}>
  <Image class="fj-light" src={light} alt={alt} />
  <Image class="fj-dark" src={dark} alt={alt} />
  {caption && <figcaption>{caption}</figcaption>}
</figure>

---
// The facts a reader wants before the prose: where a feature is, its keys, what it needs.
// Every prop is optional, and a row appears only when its prop is given.
interface Props {
  /** Menu paths, as the app prints them: `Clip ▸ Split`. */
  menu?: string | string[];
  /** Keys, as the app prints them: `⌘T`. */
  keys?: string | string[];
  /** Where else it lives: an inspector tab and section, the toolbar, a right-click menu. */
  where?: string | string[];
  /** The agent tools that do the same thing. */
  tools?: string | string[];
  /** What it needs beyond the app: a key, a permission, a model. */
  needs?: string | string[];
}

const list = (value?: string | string[]) => (value === undefined ? [] : [value].flat());
const { menu, keys, where, tools, needs } = Astro.props;
---

<dl class="fj-glance not-content">
  {
    list(menu).length > 0 && (
      <>
        <dt>Menu</dt>
        <dd>
          {list(menu).map((item) => (
            <strong>{item}</strong>
          ))}
        </dd>
      </>
    )
  }
  {
    list(keys).length > 0 && (
      <>
        <dt>Keys</dt>
        <dd>
          {list(keys).map((item) => (
            <kbd>{item}</kbd>
          ))}
        </dd>
      </>
    )
  }
  {
    list(where).length > 0 && (
      <>
        <dt>Where</dt>
        <dd>{list(where).join(' · ')}</dd>
      </>
    )
  }
  {
    list(needs).length > 0 && (
      <>
        <dt>Needs</dt>
        <dd>{list(needs).join(' · ')}</dd>
      </>
    )
  }
  {
    list(tools).length > 0 && (
      <>
        <dt>Agent tools</dt>
        <dd>
          {list(tools).map((item) => (
            <code>{item}</code>
          ))}
        </dd>
      </>
    )
  }
</dl>

---
// The exhaustive feature list: src/data/features.json as one filterable table per section.
import data from '../data/features.json';

interface Feature {
  name: string;
  summary: string;
  page: string;
  anchor?: string;
  where?: string;
  keys?: string;
  needs?: string;
}

interface Section {
  id: string;
  title: string;
  features: Feature[];
}

const sections = data.sections as Section[];
const total = sections.reduce((sum, section) => sum + section.features.length, 0);
const href = (feature: Feature) =>
  `/${feature.page}/${feature.anchor ? `#${feature.anchor}` : ''}`;
---

<div class="fj-filter not-content">
  <input
    id="fj-filter"
    type="search"
    placeholder={`Filter ${total} features by name, menu or shortcut`}
    aria-label="Filter the features"
  />
  <output id="fj-count" for="fj-filter">{total} features</output>
</div>

{
  sections.map((section) => (
    <section class="fj-section" data-section={section.id}>
      <h2 id={section.id}>{section.title}</h2>
      <table class="fj-features">
        <thead>
          <tr>
            <th scope="col">Feature</th>
            <th scope="col">What it does</th>
            <th scope="col">Where</th>
          </tr>
        </thead>
        <tbody>
          {section.features.map((feature) => (
            <tr>
              <td>
                <a href={href(feature)}>{feature.name}</a>
              </td>
              <td>{feature.summary}</td>
              <td class="fj-where">
                {feature.where}
                {feature.keys && (
                  <>
                    {' '}
                    <kbd>{feature.keys}</kbd>
                  </>
                )}
                {feature.needs && <div>Needs {feature.needs}</div>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  ))
}

<script>
  const input = document.querySelector<HTMLInputElement>('#fj-filter');
  const count = document.querySelector<HTMLOutputElement>('#fj-count');
  const sections = [...document.querySelectorAll<HTMLElement>('.fj-section')];
  const rows = sections.flatMap((section) =>
    [...section.querySelectorAll<HTMLTableRowElement>('tbody tr')].map((row) => ({
      row,
      text: row.textContent?.toLowerCase() ?? '',
    })),
  );

  input?.addEventListener('input', () => {
    const words = input.value.toLowerCase().split(/\s+/).filter(Boolean);
    let shown = 0;
    for (const { row, text } of rows) {
      row.hidden = !words.every((word) => text.includes(word));
      if (!row.hidden) shown += 1;
    }
    for (const section of sections) {
      section.hidden = !section.querySelector('tbody tr:not([hidden])');
    }
    if (count) count.textContent = `${shown} features`;
  });
</script>

