"""Carry the global npm packages from Node 22.18.0 to 22.23.4. Copies only: 22.18.0 is left whole."""
import os, shutil, sys

BASE = '/Users/kevingalligan/.local/share/mise/installs/node'
OLD, NEW = f'{BASE}/22.18.0', f'{BASE}/22.23.4'
SHIPPED = {'npm', 'corepack'}                       # each Node version brings its own
OWN_BINS = {'node', 'npm', 'npx', 'corepack', '.DS_Store'}

if not os.path.isdir(NEW):
    sys.exit(f'{NEW} is not installed')

for name in sorted(os.listdir(f'{OLD}/lib/node_modules')):
    if name in SHIPPED or name.startswith('.'):
        continue
    source, target = f'{OLD}/lib/node_modules/{name}', f'{NEW}/lib/node_modules/{name}'
    if os.path.lexists(target):
        print('already there', name)
    elif os.path.islink(source):
        os.symlink(os.readlink(source), target)     # an npm link, relative, same depth
        print('link', name, '->', os.readlink(source), 'resolves' if os.path.exists(target) else 'BROKEN')
    else:
        shutil.copytree(source, target, symlinks=True)
        print('copied', name)

for name in sorted(os.listdir(f'{OLD}/bin')):
    source, target = f'{OLD}/bin/{name}', f'{NEW}/bin/{name}'
    if name in OWN_BINS or os.path.lexists(target):
        continue
    os.symlink(os.readlink(source), target)
    print('bin', name, 'ok' if os.path.exists(target) else 'BROKEN')

