export const meta = {
  name: 'framejob-fix-guide',
  description: 'Verify and apply the fact-checkers\' findings to docs/guide and docs/graphics-api.md, one page at a time',
  phases: [{ title: 'Fix', detail: 'one agent per guide page: confirm each finding in the code, then correct the page' }],
}

const S = args.scratch
const R = args.repo

const RESULT = { type: 'object', properties: { findings: { type: 'number' }, applied: { type: 'number' }, rejected: { type: 'array', items: { type: 'string' } }, app_defects: { type: 'array', items: { type: 'object', properties: { title: { type: 'string' }, evidence: { type: 'string' }, severity: { type: 'string' } }, required: ['title', 'evidence'] } } }, required: ['findings', 'applied', 'rejected', 'app_defects'] }

const fix = (page) => {
  const target = page === 'unplaced'
    ? 'the files the findings name, most of them docs/graphics-api.md (which graphic/tests/reference.rs runs, so keep each js block valid and unchanged unless a finding is about it)'
    : `docs/guide/${page}.md`
  return agent(`You are correcting the user guide of Frame Job, a native macOS video editor, in ${R} (your working directory). The guide's rule is that every claim is written from the code.

While checking a new documentation site against the code, fact-checkers noted where the guide was wrong. Your findings are in ${S}/inventory/guide-fixes/${page}.txt, and they apply to ${target}. A finding may name another guide page in passing. Line numbers may have drifted.

Findings are claims, not facts. For each one:
1. Read the guide's passage and the code the finding cites, and any other code that settles it: app/Sources, core/src, graphic, mcp-proxy, agent.
2. If the guide is wrong or misleading, correct it with the smallest edit that makes it true, in the guide's own voice and style.
3. If the guide only leaves out a detail it doesn't need, or the finding is mistaken, leave it and record why.
Do not restructure, restyle or add sections. Keep headings, since other pages link to them, and keep explicit anchors. Don't add spec IDs or road-map references. The old product name must never appear. Nothing dev-only belongs in the guide.

Two facts already settled in the code: real arrow keys don't nudge clips on the canvas (PreviewCanvasView.handleKey's guard rejects the .numericPad and .function flags they carry), so they fall through to frame stepping, and keypad Enter fails the same way in crop mode. Copy, Cut and Paste of a nest clip fail, because clipboardPayload carries no nests and core's reachable_nests refuses the paste. If your page claims otherwise, correct it to say what happens now.

Shell note: commands with heredocs, loops or variables can be refused here, so write any script to a file under ${S}/work/ and run it as one plain command. Do not run git. Edit only your target. Other agents own the other guide pages.

Return how many findings you read, how many you applied, each one you rejected and why, and any app defect the code shows, with file:line and a severity (data-loss, broken, minor, cosmetic).`, { label: 'guide:' + page, phase: 'Fix', schema: RESULT, effort: 'high' })
}

const results = await parallel(args.pages.map((page) => () => fix(page).then((r) => r && { page, ...r })))
const done = results.filter(Boolean)
const missed = args.pages.filter((p) => !done.find((r) => r.page === p))
if (missed.length) log('No result: ' + missed.join(', '))
return {
  missed,
  findings: done.reduce((n, r) => n + r.findings, 0),
  applied: done.reduce((n, r) => n + r.applied, 0),
  rejected: done.flatMap((r) => r.rejected.map((x) => ({ page: r.page, item: x }))),
  app_defects: done.flatMap((r) => r.app_defects.map((d) => ({ page: r.page, ...d }))),
}

