  const implPrompt = specRef === 'request.md'
    ? `Handoff dir: ${H}. Read request.md and 00-triage.md. No spec exists; implement the request directly, touching only files_likely_touched unless you justify otherwise in your notes. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD).${commitRule} Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
    : `Handoff dir: ${H}. Read ${specRef}. Implement it. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD).${commitRule} Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
  const impl = await agent(implPrompt, opts('implement', { agentType: 'lc-implementer', schema: BUILD, isolation: 'worktree' }))
  if (!impl) return { ap: P.ap, status: 'failed', detail: 'implementer returned nothing' }
  if (impl.status === 'stop') return { ...stopped(impl.stop_reason || impl.summary), worktree: impl.worktree, tip: impl.tip }
  const base = impl.base
