      prev = rev.findings
      const fx = await agent(`Handoff dir: ${H}. Read ${reviewFile} and the git diff. ${diffNote()} Your worktree is fresh: first \`git reset --hard ${tip}\`, then CoW-copy the build caches from ${worktrees[worktrees.length - 1]} as ${COMMON} says. Fix every blocker and should-fix. Re-run the spec's verification commands that your fixes can affect. Commit in your worktree${P.toll ? ' (a fix to a toll that is not a pure move goes in its own commit after the tolls)' : ''}. Write 06-fix-notes-${pass}.md. ${note(L, P)} Return base ${base} unchanged, your new tip, worktree and branch; status stop with STOP: at the top of the notes if you must stop.`,
        opts(`fix ${pass}`, { agentType: 'lc-fixer', schema: BUILD, isolation: 'worktree' }))
      if (!fx || fx.status === 'stop') return { ap: P.ap, status: 'stopped', detail: fx ? (fx.stop_reason || fx.summary) : 'fixer returned nothing', tip, worktrees }
      tip = fx.tip
      worktrees.push(fx.worktree)
      const next = `07-review-${pass + 1}.md`
      rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 04-impl-notes.md, 04-checks.txt, every 06-fix-notes-*.md so far, ${reviewFile}, and the git diff. ${diffNote()} Write ${next}. ${note(L, P)}`,
        opts(`re-review ${pass + 1}`, { agentType: 'lc-reviewer', schema: REVIEW }))
      reviewFile = next
    }
    if (!rev) return { ap: P.ap, status: 'failed', detail: 'reviewer returned nothing', tip, worktrees }
    log(`${P.ap}: review passed (${reviewFile})`)
  } else {
    log(`${P.ap}: review skipped (diff < 80 lines, checks pass)`)
  }

  const landing = P.toll
    ? `2. \`git cherry-pick ${base}..${tip}\` (WITH commits: each toll stays its own commit, as the rule "a pure move landed and gated alone" wants; keep each commit's message, appending the trailer line below to any that lacks it via \`git commit --amend\` immediately after that pick only if needed). Resolve conflicts keeping both intents (another lane may have landed spec index cells, history entries or the road map meanwhile). If you cannot resolve one with confidence, \`git cherry-pick --abort\`, release the lock, and return conflict-unresolved naming the files.`
    : `2. \`git cherry-pick --no-commit ${base}..${tip}\`. Resolve conflicts keeping both intents (other phases landed meanwhile: decision index rows and Lines cells, spec index cells, guide pages, catalogs, format version — if another landed phase already took this phase's RC_FORMAT_VERSION number, renumber this phase's to the next free number in format.rs, the header and its schema_vN.rs, and fix what reads it). If you cannot resolve one with confidence, \`git cherry-pick --abort\`, release the lock, and return conflict-unresolved naming the files.`
  const commitStep = P.toll
    ? `6. Commit the record, the CLAUDE.md edits and any conflict fix-ups as ONE further commit by explicit paths: subject "Record ${P.ap} (road map creator-jobs)"; body: what landed (the toll commits by short sha), "Verified:" (make gate and the move diffs), "Owed:" (or nothing); last line exactly: Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>. Never commit FrameJob.xcodeproj, tools/proof/work/, tools/proof/media/ or build products.`
    : `6. Stage everything the phase changed by explicit path (never FrameJob.xcodeproj, tools/proof/work/, tools/proof/media/, build products) and commit ONE commit: a subject saying what now works, ending "(road map creator-jobs ${P.ap})"; body: what changed, "Verified:" (the checks that passed incl. the Release proof and make gate), "Owed:" (or nothing); last line exactly: Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>.`

  const integ = await locked(() => agent(`You integrate one finished litecode phase of road map "creator-jobs" (${P.ap}) onto the integration branch. Integration worktree I=${I} (branch worktree-creator-jobs); your shell starts there; run every command there with plain separate commands (the session refuses git aimed at another checkout and compound commands it cannot verify; a plain \`for\`/\`until\` wait loop with sleep inside one Bash call is fine). Handoff dir H=${H}. The phase's commits are ${base}..${tip} (shared refs); its worktrees: ${worktrees.join(', ')}.

0. Take the lock: \`mkdir ${LOCK}\`. If it already exists, wait (a Bash loop retrying mkdir every 10 s, up to 9 minutes per call, repeated up to 6 calls) and then take it. Then check I is idle: \`git status --porcelain\` prints nothing (untracked build caches excepted) AND \`git rev-parse --git-path CHERRY_PICK_HEAD\` names a file that does not exist. If it is not idle, \`rmdir ${LOCK}\` and return failed naming what is dirty. RELEASE the lock (\`rmdir ${LOCK}\`) at the end on EVERY outcome, landed or not.

Steps, in order:
1. Read H/${specRef}, H/04-impl-notes.md, H/04-checks.txt${reviewFile ? ', every H/06-fix-notes-*.md and H/' + reviewFile : ''}. Collect every "CLAUDE.md edits owed" item and every "To file" item.
${landing}
3. Apply the CLAUDE.md edits owed in the files' own style (rulebook prose, no status paragraphs).
4. Write the phase's record into I's designs/creator-jobs.md as a "#### ${P.ap}'s record (<today, from \`date +%F\`>)" section placed at the END of ${P.ap}'s own section (just before the next "####" or "###" heading after "#### ${P.ap} —" or "### ${P.ap} —"), in the style of "CJ0a's record": what landed (commits, files, decisions), what was measured (numbers only as printed in the notes/checks), what the review found and how it was resolved, and what is owed (manual checks, To-file items). Keep it compact.
5. \`make gate\` in the foreground (Bash timeout 600000). If it fails because of the merge or steps 3–4, fix and re-run (at most two fixes); any other failure → \`git reset --hard\` is FORBIDDEN; instead leave I as is, release the lock, and return failed with the gate's last lines.
${commitStep}
7. Release the lock (\`rmdir ${LOCK}\`).
8. Each "To file" item: \`gh issue create --label ai-drafted --label low-priority --title ... --body ...\` (body names the commit). Return them in filed.
9. Remove the phase's worktrees and branches: for each worktree path above, find its branch with \`git worktree list --porcelain\`, then \`git worktree remove <path>\` (add --force only if that refuses because of untracked build caches) and \`git branch -D <branch>\`.
10. Append one line to ${LOG}: "<date> <short sha> ${P.ap} <subject>".
Never push, never touch /Users/kevingalligan/devel/framejob (main), never force-move a branch. Return the short sha of your last commit. If the phase was split and a remainder (e.g. XXn2, XXnb) is still to be built, say so plainly in detail as "REMAINDER: <id>".`,
    opts('integrate', { agentType: 'general-purpose', schema: INTEGRATE })))
  if (!integ) return { ap: P.ap, status: 'failed', detail: 'integrator returned nothing', tip, worktrees }
  if (integ.status !== 'landed') return { ap: P.ap, status: integ.status, detail: integ.detail, tip, worktrees }
  log(`${P.ap}: landed as ${integ.sha}`)
  return { ap: P.ap, status: 'landed', sha: integ.sha, filed: integ.filed || [], detail: integ.detail }
}

async function runLane(L) {
  const out = []
  const queue = L.phases.slice()
  while (queue.length) {
    const P = queue.shift()
    const r = await runPhase(L, P)
    out.push(r)
    if (r.status !== 'landed') {
      for (const rest of queue) out.push({ ap: rest.ap, status: 'not-run', detail: `lane halted at ${P.ap}` })
      break
    }
    const m = /REMAINDER:\s*([A-Z]{2}[0-9]+[a-z]?[0-9]?)/.exec(r.detail || '')
    if (m && m[1] !== P.ap && !queue.some(q => q.ap === m[1])) {
      const rid = m[1]
      const dir = 'cj-' + rid.toLowerCase()
      log(`${P.ap}: remainder ${rid} queued next`)
      await agent(`Create the directory ${HROOT}${dir} if it does not exist and, if ${HROOT}${dir}/request.md does not exist, write it. It is a litecode request for road map "creator-jobs" phase ${rid}, the remainder of ${P.ap}, in lane ${L.lane.toUpperCase()}. Copy the first paragraph (the owner's words) and the closing "Decisions so far…" and "Binding rules…" paragraphs from ${HROOT}cj-${P.ap.toLowerCase()}/request.md. Between them, write: "Build ${rid}, the remainder of ${P.ap} that ${P.ap}'s record in designs/creator-jobs.md names as still to be built (read that record and ${P.ap}'s final spec, ${HROOT}cj-${P.ap.toLowerCase()}/03-spec-final.md). ${P.ap} has landed (${r.sha})." and quote the integrator's remainder line: ${JSON.stringify((r.detail || '').slice((r.detail || '').indexOf('REMAINDER')))}. Reply "done".`, { label: `${rid} write request`, phase: L.phase, effort: 'low' })
      queue.unshift({ ap: rid, dir })
    }
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)
